import {LitElement,css,html} from 'lit';
import {customElement,property,state} from 'lit/decorators.js';
type Cue={start:number;end:number;text:string};
const KEY='savanna.prefs.v1';
function prefs(){try{return {enabled:false,extended:false,mode:'audio',...JSON.parse(localStorage.getItem(KEY)||'{}').ad};}catch{return {enabled:false,extended:false,mode:'audio'};}}
@customElement('savanna-audio-description')
export class SavannaAudioDescription extends LitElement{
 static styles=css`:host{display:block;font:16px/1.5 system-ui;color:inherit}button,select{min-height:44px;padding:8px 12px;border:1px solid #72548a;border-radius:8px;background:white;color:#241b2b;font:inherit}button:focus-visible,select:focus-visible{outline:3px solid #e09b00;outline-offset:2px}.controls{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.ad-badge{display:inline-flex;align-items:center;gap:6px;padding:4px 10px;border-radius:16px;background:#4caf50;color:white;font-size:13px;font-weight:700;animation:fadeIn .3s}@keyframes fadeIn{from{opacity:0}to{opacity:1}}.ad-badge-off{background:#666}`;
 @property() src=''; @property({attribute:'text-vtt'}) textVtt=''; @property({type:Number,attribute:'offset-ms'}) offsetMs=0;
 @state() private p=prefs(); @state() private status='Audio description is off.'; @state() private cues:Cue[]=[]; @state() private active='';
 private player?:HTMLElement; private media?:HTMLMediaElement; private audio?:HTMLAudioElement; private wasPlaying=false; private last=-1;
 connectedCallback(){super.connectedCallback();this.player=this.closest('savanna-player') as HTMLElement|undefined;this.media=(this.player as any)?.media;this.player?.addEventListener('savanna:timeupdate',this.time as EventListener);if(this.textVtt)void this.load();}
 disconnectedCallback(){this.player?.removeEventListener('savanna:timeupdate',this.time as EventListener);this.stop(false);super.disconnectedCallback();}
 firstUpdated(){this.audio=this.renderRoot.querySelector('audio')||undefined;if(!this.media){this.player=this.closest('savanna-player') as HTMLElement|undefined;this.media=(this.player as any)?.media;}}
 private save(){try{const a=JSON.parse(localStorage.getItem(KEY)||'{}');a.ad=this.p;localStorage.setItem(KEY,JSON.stringify(a));}catch{}}
 private async load(){try{const r=await fetch(this.textVtt);if(!r.ok)throw Error();const v=await r.text();const blocks=v.replace(/\r/g,'').split(/\n\n+/);this.cues=blocks.map(b=>{const lines=b.split('\n'),i=lines.findIndex(x=>x.includes('-->'));if(i<0)return null;const sec=(s:string)=>s.trim().split(/[,.]/)[0].split(':').map(Number).reduce((a,n)=>a*60+n,0)+Number('0.'+(s.split(/[,.]/)[1]||0));return {start:sec(lines[i].split('-->')[0]),end:sec(lines[i].split('-->')[1]),text:lines.slice(i+1).join(' ')};}).filter(Boolean) as Cue[];}catch{this.status='Text description could not be loaded.';}}
 /** Called by the owning player for its D shortcut; no competing global listener is installed. */
 public toggle(){if(this.p.enabled)this.stop();else void this.play();}
 private time=(e:Event)=>{const d=(e as CustomEvent).detail;if(!d)return;if(this.p.enabled&&this.p.mode==='text'){const c=this.cues.find(x=>d.time>=x.start&&d.time<x.end);if(c&&c.text!==this.active){this.active=c.text;this.status=c.text;}}if(this.p.enabled&&this.p.mode==='audio'&&this.audio&&this.src){const target=Math.max(0,d.time-this.offsetMs/1000);if(Math.abs(this.audio.currentTime-target)>.45)try{this.audio.currentTime=target;}catch{}this.audio.playbackRate=d.rate||1;if(d.paused){this.audio.pause();}else if(this.audio.paused)void this.audio.play().catch(()=>{});}};
 private async play(){this.p={...this.p,enabled:true};this.save();if(this.p.mode==='text'){this.status=this.active||'Text descriptions are enabled.';return;}if(!this.src||!this.audio){this.status='Recorded audio description is not available.';return;}if(this.media){this.wasPlaying=!this.media.paused;try{this.audio.currentTime=Math.max(0,this.media.currentTime-this.offsetMs/1000);}catch{}this.audio.playbackRate=this.media.playbackRate;}try{await this.audio.play();this.status='Audio description playing.';}catch{this.status='Press Play to start the description.';}}
 private stop(persist=true){this.audio?.pause();if(this.p.extended&&this.wasPlaying)void this.media?.play().catch(()=>{});this.wasPlaying=false;if(persist){this.p={...this.p,enabled:false};this.save();}this.status='Audio description stopped.';}
 private descriptionEnded=()=>{if(this.p.extended&&this.wasPlaying)void this.media?.play().catch(()=>{});this.wasPlaying=false;this.p={...this.p,enabled:false};this.save();this.status='Description finished.';};
 private extended(v:boolean){this.p={...this.p,extended:v};this.save();if(v&&this.audio&&!this.audio.paused){this.wasPlaying=!!this.media&&!this.media.paused;this.media?.pause();}}
 render(){const badge=this.p.enabled?html`<span class="ad-badge" role="status" aria-label="Audio description active">🔊 AD ON</span>`:html`<span class="ad-badge ad-badge-off" aria-label="Audio description off">AD OFF</span>`;return html`<div class="controls">${badge}<button type="button" aria-pressed=${String(this.p.enabled)} aria-label="Audio description ${this.p.enabled?'on':'off'}" @click=${()=>this.p.enabled?this.stop():void this.play()}>Audio description: ${this.p.enabled?'On':'Off'}</button><label>Mode <select .value=${this.p.mode} @change=${(e:Event)=>{this.p={...this.p,mode:(e.target as HTMLSelectElement).value};this.save();}}><option value="audio">Recorded audio</option><option value="text">Text descriptions</option></select></label><button @click=${this.play}>Play description</button><button @click=${this.stop}>Stop</button><label><input type="checkbox" .checked=${this.p.extended} @change=${(e:Event)=>this.extended((e.target as HTMLInputElement).checked)}> Extended AD (pause lesson)</label></div><audio preload="metadata" .src=${this.src} @play=${()=>{if(this.p.extended){this.wasPlaying=!!this.media&&!this.media.paused;this.media?.pause();}}} @ended=${this.descriptionEnded} @error=${()=>this.status='Recorded description failed to load.'}></audio><p role="status" aria-live="polite">${this.status}</p>`;}
}
